def get_plant_info(label: str) -> dict:
    """Return an educational record; unknown labels get a conservative fallback."""
    key = str(label).strip().replace(" ", "_")
    entry = _PLANTS.get(key)
    if entry:
        common, about, traditional, food, safety, botanical = entry
    else:
        common, about, traditional, food, safety, botanical = (
            key.replace("_", " "),
            "No verified plant-specific description is available in this guide yet.",
            "No medicinal-use claim is provided until the identity and a reliable source are checked.",
            "Not cleared for consumption. Never eat a plant based only on an image-classifier result.",
            "Confirm the exact species with a qualified botanist or local agricultural extension service.",
            "",
        )
    source_url = KEW_SEARCH_URL + quote(botanical) if botanical else ""
    if key == "Ashwagandha":
        source_url = "https://www.nccih.nih.gov/health/ashwagandha"
    elif key == "Castor":
        source_url = "https://www.poison.org/articles/what-happens-if-i-eat-castor-beans-222"
    elif key == "Betel_Nut":
        source_url = "https://stacks.cdc.gov/view/cdc/43373"
    elif key in {"Arali", "Ekka", "Nithyapushpa", "Ganike", "Nagadali"}:
        source_url = POISON_CONTROL_URL
    return {
        "common_name": common,
        "about": about,
        "traditional_use": traditional,
        "food_context": food,
        "safety": safety,
        "botanical": botanical,
        "source_url": source_url,
        "general_safety_url": POISON_CONTROL_URL,
    }
